LL floor_sum(LL n, LL m, LL a, LL b) { LL res = 0; if (a < 0) { LL ad = (a - (m - 1)) / m; res += ad * n * (n - 1) / 2; a -= ad * m; } if (b < 0) { LL bd = (b - (m - 1)) / m; res += bd * n; b -= bd * m; } while (true) { if (a >= m) { res += (n - 1) * n / 2 * (a / m); a %= m; } if (b >= m) { res += n * (b / m); b %= m; } LL ym = (a * n + b) / m; if (ym == 0) break; LL xm = ym * m - b; res += (n - (xm + a - 1) / a) * ym; n = ym; b = (a - xm % a) % a; swap(a, m); } return res; }
